<?php
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence');exit;}
function rp_schema():array{return [
 "CREATE TABLE IF NOT EXISTS rp_definitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,dataset VARCHAR(30) NOT NULL,filters_json TEXT NOT NULL,columns_json TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS rp_schedules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,definition_id BIGINT UNSIGNED NOT NULL,frequency VARCHAR(12) NOT NULL,window_days INT NOT NULL,next_due DATE NOT NULL,active TINYINT NOT NULL DEFAULT 1,last_error VARCHAR(160) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS rp_exports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,dataset VARCHAR(30) NOT NULL,title VARCHAR(180) NOT NULL,csv MEDIUMTEXT NOT NULL,event_key VARCHAR(100) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY export_once(tenant_id,event_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS rp_cohorts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,year_name VARCHAR(30) NOT NULL,captured_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_year(tenant_id,year_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS rp_members(tenant_id BIGINT UNSIGNED NOT NULL,cohort_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NULL,class_name VARCHAR(120) NOT NULL,PRIMARY KEY(tenant_id,cohort_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function rp_columns():array{return [
 'executive'=>['metric','value'], 'enrolment'=>['class','students','active','new_in_period'], 'admissions'=>['stage','applications','enrolled','conversion_percent'], 'academics'=>['session','term','subject','approved_scores','mean_percent'], 'attendance'=>['class','recorded','present_or_late','absent','attendance_percent'], 'finance'=>['metric','kobo'], 'workload'=>['teacher','allocations','weekly_periods','weekly_minutes'], 'retention'=>['cohort','students','retained_from_previous','captured_at'], 'hr'=>['metric','value'], 'operations'=>['metric','value']
];}
function rp_require(array $u,string $key):void{if(!isset(rp_columns()[$key]))throw new RuntimeException('Choose an allowlisted report dataset.');ix_need($u,'reports_view');if($key==='finance')ix_need($u,'finance_reports');if($key==='hr')ix_need($u,'hr_reports');}
function rp_filters(array $f):array{$from=op_date((string)($f['from']??date('Y-01-01')));$to=op_date((string)($f['to']??date('Y-m-d')));if($to<$from||(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days>3660)throw new RuntimeException('Use a valid reporting range of at most ten years.');$class=(int)($f['class_id']??0);if($class<0)throw new RuntimeException('Invalid class filter.');return ['from'=>$from,'to'=>$to,'class_id'=>$class];}
function rp_report(array $u,string $key,array $filters=[]):array{rp_require($u,$key);$f=rp_filters($filters);if($f['class_id'])sv_own('classes',$u,$f['class_id']);return rp_data((int)$u['tenant_id'],$key,$f);}
/** Internal aggregate query set. Routes must call rp_report or verified HQ/API scope first. No free-form SQL. */
function rp_data(int $tid,string $key,array $f):array{
 $from=$f['from'].' 00:00:00';$to=$f['to'].' 23:59:59';$class=(int)$f['class_id'];
 if($key==='executive')return [['metric'=>'Current enrolled records','value'=>(int)g('SELECT COUNT(*) FROM students WHERE tenant_id=?',[$tid])],['metric'=>'Active student profiles','value'=>(int)g("SELECT COUNT(*) FROM students s LEFT JOIN sis_student_details d ON d.student_id=s.id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND COALESCE(d.status,'active')='active'",[$tid])],['metric'=>'Applications created in range','value'=>(int)g('SELECT COUNT(*) FROM ecosystem_applications WHERE tenant_id=? AND created_at BETWEEN ? AND ?',[$tid,$from,$to])],['metric'=>'Recorded attendance in range','value'=>(int)g('SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND attendance_date BETWEEN ? AND ?',[$tid,$f['from'],$f['to']])]];
 if($key==='enrolment')return q("SELECT COALESCE(c.name,'Unassigned') class,COUNT(*) students,SUM(COALESCE(d.status,'active')='active') active,SUM(COALESCE(d.admission_date,DATE(s.created_at)) BETWEEN ? AND ?) new_in_period FROM students s LEFT JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id LEFT JOIN sis_student_details d ON d.student_id=s.id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=?".($class?' AND s.class_id=?':'')." GROUP BY c.id,c.name ORDER BY class",$class?[$f['from'],$f['to'],$tid,$class]:[$f['from'],$f['to'],$tid])->fetchAll();
 if($key==='admissions')return q("SELECT COALESCE(c.stage,a.status) stage,COUNT(*) applications,SUM(c.student_id IS NOT NULL) enrolled,ROUND(100*SUM(c.student_id IS NOT NULL)/COUNT(*),2) conversion_percent FROM ecosystem_applications a LEFT JOIN crm_cases c ON c.application_id=a.id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.created_at BETWEEN ? AND ? GROUP BY COALESCE(c.stage,a.status) ORDER BY stage",[$tid,$from,$to])->fetchAll();
 if($key==='academics')return q("SELECT a.session_name session,a.term_name term,s.name subject,COUNT(*) approved_scores,ROUND(AVG(sc.score/a.max_score*100),2) mean_percent FROM ac_scores sc JOIN ac_assessments a ON a.id=sc.assessment_id AND a.tenant_id=sc.tenant_id JOIN subjects s ON s.id=a.subject_id AND s.tenant_id=a.tenant_id JOIN ac_term_approvals p ON p.tenant_id=a.tenant_id AND p.class_id=a.class_id AND p.session_name=a.session_name AND p.term_name=a.term_name AND p.status='published' WHERE sc.tenant_id=? AND sc.status='approved' AND a.max_score>0 AND p.published_at BETWEEN ? AND ?".($class?' AND a.class_id=?':'')." GROUP BY a.session_name,a.term_name,s.id,s.name ORDER BY session,term,subject",$class?[$tid,$from,$to,$class]:[$tid,$from,$to])->fetchAll();
 if($key==='attendance')return q("SELECT COALESCE(c.name,'Unassigned') class,COUNT(*) recorded,SUM(a.status IN ('present','late')) present_or_late,SUM(a.status='absent') absent,ROUND(100*SUM(a.status IN ('present','late'))/COUNT(*),2) attendance_percent FROM attendance a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id LEFT JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id WHERE a.tenant_id=? AND a.attendance_date BETWEEN ? AND ?".($class?' AND s.class_id=?':'')." GROUP BY c.id,c.name ORDER BY class",$class?[$tid,$f['from'],$f['to'],$class]:[$tid,$f['from'],$f['to']])->fetchAll();
 if($key==='finance')return [['metric'=>'Confirmed external collections in period (includes advances/overpayments)','kobo'=>(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM fn_payments WHERE tenant_id=? AND status='confirmed' AND channel NOT IN ('credit','school_wallet') AND confirmed_at BETWEEN ? AND ?",[$tid,$from,$to])],['metric'=>'Internal credit/wallet allocations in period','kobo'=>(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM fn_payments WHERE tenant_id=? AND status='confirmed' AND channel IN ('credit','school_wallet') AND confirmed_at BETWEEN ? AND ?",[$tid,$from,$to])],['metric'=>'Net billed for invoices created in period','kobo'=>(int)g('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo)),0) FROM fn_invoices WHERE tenant_id=? AND created_at BETWEEN ? AND ?',[$tid,$from,$to])],['metric'=>'Current outstanding on that invoice cohort (not historical closing debt)','kobo'=>(int)g('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo-paid_kobo)),0) FROM fn_invoices WHERE tenant_id=? AND created_at BETWEEN ? AND ?',[$tid,$from,$to])]];
 if($key==='workload')return q("SELECT u.name teacher,(SELECT COUNT(*) FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name WHERE a.tenant_id=u.tenant_id AND a.teacher_id=u.id) allocations,(SELECT COUNT(*) FROM ac_timetable t JOIN classes c ON c.id=t.class_id AND c.tenant_id=t.tenant_id AND c.session_name=t.session_name WHERE t.tenant_id=u.tenant_id AND t.teacher_id=u.id) weekly_periods,(SELECT COALESCE(SUM(TIME_TO_SEC(TIMEDIFF(t.end_time,t.start_time))/60),0) FROM ac_timetable t JOIN classes c ON c.id=t.class_id AND c.tenant_id=t.tenant_id AND c.session_name=t.session_name WHERE t.tenant_id=u.tenant_id AND t.teacher_id=u.id) weekly_minutes FROM users u WHERE u.tenant_id=? AND u.role='teacher' AND u.active=1 ORDER BY u.name",[$tid])->fetchAll();
 if($key==='retention'){$out=[];$prior=null;foreach(q('SELECT * FROM rp_cohorts WHERE tenant_id=? ORDER BY year_name,id',[$tid])->fetchAll() as $c){$n=(int)g('SELECT COUNT(*) FROM rp_members WHERE tenant_id=? AND cohort_id=?',[$tid,$c['id']]);$retained=$prior===null?null:(int)g('SELECT COUNT(*) FROM rp_members a JOIN rp_members b ON b.tenant_id=a.tenant_id AND b.student_id=a.student_id WHERE a.tenant_id=? AND a.cohort_id=? AND b.cohort_id=?',[$tid,$prior,$c['id']]);$out[]=['cohort'=>$c['year_name'],'students'=>$n,'retained_from_previous'=>$retained??'First snapshot','captured_at'=>$c['created_at']];$prior=(int)$c['id'];}return $out;}
 if($key==='hr')return array_merge(q("SELECT CONCAT('Employment: ',status) metric,COUNT(*) value FROM hr_employees WHERE tenant_id=? GROUP BY status",[$tid])->fetchAll(),[['metric'=>'Paid payroll gross in requested periods (kobo)','value'=>(int)g("SELECT COALESCE(SUM(l.gross_kobo),0) FROM hr_paylines l JOIN hr_payruns r ON r.id=l.run_id AND r.tenant_id=l.tenant_id WHERE l.tenant_id=? AND r.status='paid' AND r.period BETWEEN ? AND ?",[$tid,substr($f['from'],0,7),substr($f['to'],0,7)])]]);
 if($key==='operations')return [['metric'=>'Active transport assignments','value'=>(int)g("SELECT COUNT(*) FROM tm_assignments WHERE tenant_id=? AND status='active'",[$tid])],['metric'=>'Active vehicles','value'=>(int)g("SELECT COUNT(*) FROM vehicles WHERE tenant_id=? AND status='active'",[$tid])],['metric'=>'Active boarding allocations','value'=>(int)g("SELECT COUNT(*) FROM bd_allocations WHERE tenant_id=? AND status='active'",[$tid])],['metric'=>'Registered boarding beds','value'=>(int)g('SELECT COUNT(*) FROM bd_beds WHERE tenant_id=?',[$tid])],['metric'=>'Private transport incidents in period (count only)','value'=>(int)g("SELECT COUNT(*) FROM tm_events WHERE tenant_id=? AND kind='incident' AND created_at BETWEEN ? AND ?",[$tid,$from,$to])]];
 throw new RuntimeException('Unknown dataset.');
}
function rp_csv(array $columns,array $rows):string{$f=fopen('php://temp','r+');fputcsv($f,$columns,',','"','');foreach($rows as $row){$cells=[];foreach($columns as $c){$v=(string)($row[$c]??'');$cells[]=preg_match('/^[=+@\-\t\r]/',$v)?"'".$v:$v;}fputcsv($f,$cells,',','"','');}rewind($f);$csv=stream_get_contents($f);fclose($f);return $csv;}
function rp_export(array $u,array $definition,string $key,?array $override=null):int{global $pdo;rp_require($u,$definition['dataset']);$rows=rp_report($u,$definition['dataset'],$override??json_decode($definition['filters_json'],true));$columns=json_decode($definition['columns_json'],true);if(!$columns||array_diff($columns,rp_columns()[$definition['dataset']]))throw new RuntimeException('Invalid export columns.');$csv=rp_csv($columns,$rows);if(strlen($csv)>2000000)throw new RuntimeException('Export too large; narrow the report.');q('INSERT IGNORE INTO rp_exports(tenant_id,user_id,dataset,title,csv,event_key,expires_at) VALUES(?,?,?,?,?,?,?)',[$u['tenant_id'],$u['id'],$definition['dataset'],$definition['name'],$csv,$key,date('Y-m-d H:i:s',time()+max(1,ix_setting((int)$u['tenant_id'],'export_days'))*86400)]);return (int)g('SELECT id FROM rp_exports WHERE tenant_id=? AND event_key=?',[$u['tenant_id'],$key]);}
function rp_download(array $u,int $id):void{$r=ix_own('rp_exports',$u,$id);rp_require($u,$r['dataset']);if(((int)$r['user_id']!==(int)$u['id']&&$u['role']!=='school_admin')||$r['expires_at']<=date('Y-m-d H:i:s'))throw new RuntimeException('Export unavailable.');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="school-report-'.$id.'.csv"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');echo $r['csv'];exit;}
function rp_forecast(array $u,int $days,int $bps,int $opening,int $outflow):array{ix_need($u,'finance_reports');ix_need($u,'reports_view');if($days<1||$days>365||$bps<0||$bps>10000||$opening<0||$outflow<0)throw new RuntimeException('Invalid forecast assumptions.');$debt=(int)g("SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo-paid_kobo)),0) FROM fn_invoices WHERE tenant_id=? AND (due_date IS NULL OR due_date<=?)",[$u['tenant_id'],date('Y-m-d',time()+$days*86400)]);$rows=[];foreach(['Low'=>max(0,$bps-1500),'Base'=>$bps,'High'=>min(10000,$bps+1500)] as $scenario=>$rate){$cash=op_percent($debt,$rate);$rows[]=['scenario'=>$scenario,'eligible_receivables_kobo'=>$debt,'collection_percent'=>$rate/100,'estimated_collection_kobo'=>$cash,'ending_cash_kobo'=>$opening+$cash-$outflow,'shortfall_kobo'=>max(0,$outflow-$opening-$cash)];}return $rows;}
function rp_run(int $tid,int $limit=50):int{$count=0;foreach(q('SELECT id FROM rp_schedules WHERE tenant_id=? AND active=1 AND next_due<=CURRENT_DATE() LIMIT '.max(1,min(100,$limit)),[$tid])->fetchAll() as $r){try{sv_tx(function()use($tid,$r,&$count){$s=q('SELECT * FROM rp_schedules WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['id']])->fetch();if(!$s||!$s['active']||$s['next_due']>date('Y-m-d'))return;$u=ix_fresh($tid,(int)$s['user_id']);$d=ix_own('rp_definitions',$u,(int)$s['definition_id']);if((int)$d['user_id']!==(int)$u['id'])throw new RuntimeException('Definition owner changed.');$f=json_decode($d['filters_json'],true);$f['from']=date('Y-m-d',time()-((int)$s['window_days']-1)*86400);$f['to']=date('Y-m-d');rp_export($u,$d,'SCHEDULE-'.$s['id'].'-'.$s['next_due'],$f);$next=(new DateTimeImmutable(date('Y-m-d')))->modify(['daily'=>'+1 day','weekly'=>'+7 days','monthly'=>'+1 month'][$s['frequency']])->format('Y-m-d');q('UPDATE rp_schedules SET next_due=?,last_error=NULL WHERE tenant_id=? AND id=?',[$next,$tid,$s['id']]);$count++;});}catch(Throwable $e){q("UPDATE rp_schedules SET active=0,last_error='Owner permission or report validation changed; review schedule' WHERE tenant_id=? AND id=?",[$tid,$r['id']]);}}q('DELETE FROM rp_exports WHERE tenant_id=? AND expires_at<NOW()',[$tid]);return $count;}
function rp_action(array $u,string $a):string{
 $tid=(int)$u['tenant_id'];if($a==='definition'){$key=sv_enum('dataset',array_keys(rp_columns()));rp_require($u,$key);$f=rp_filters($_POST);if($f['class_id'])sv_own('classes',$u,$f['class_id']);$cols=array_values(array_unique(array_filter(array_map('trim',explode(',',op_text('columns',500,true))))));if(!$cols||array_diff($cols,rp_columns()[$key]))throw new RuntimeException('Choose only the dataset’s listed columns.');q('INSERT INTO rp_definitions(tenant_id,user_id,name,dataset,filters_json,columns_json) VALUES(?,?,?,?,?,?)',[$tid,$u['id'],op_text('name',180,true),$key,json_encode($f),json_encode($cols)]);return 'Allowlisted report definition saved; no free-form SQL is accepted.';}
 if($a==='export'||$a==='schedule'){$d=ix_own('rp_definitions',$u,op_id('definition_id'));rp_require($u,$d['dataset']);if((int)$d['user_id']!==(int)$u['id'])throw new RuntimeException('Use your own report definition.');if($a==='export'){$id=rp_export($u,$d,'MANUAL-'.bin2hex(random_bytes(12)));return 'Private CSV export #'.$id.' generated.';}q('INSERT INTO rp_schedules(tenant_id,user_id,definition_id,frequency,window_days,next_due) VALUES(?,?,?,?,?,CURRENT_DATE())',[$tid,$u['id'],$d['id'],sv_enum('frequency',['daily','weekly','monthly']),sv_qty('window_days',3660)]);return 'Private export schedule saved. Configure the Intelligence cron worker; no email attachment is sent automatically.';}
 if($a==='stop_schedule'){$s=ix_own('rp_schedules',$u,op_id('schedule_id'));if((int)$s['user_id']!==(int)$u['id']&&$u['role']!=='school_admin')throw new RuntimeException('Schedule unavailable.');q('UPDATE rp_schedules SET active=0 WHERE tenant_id=? AND id=?',[$tid,$s['id']]);return 'Schedule disabled.';}
 if($a==='cohort'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');return sv_tx(function()use($u,$tid){$year=op_text('year_name',30,true);if(!preg_match('/^\d{4}\/\d{4}$/D',$year)||(int)substr($year,5,4)!==(int)substr($year,0,4)+1)throw new RuntimeException('Use academic year YYYY/YYYY+1.');q('INSERT INTO rp_cohorts(tenant_id,year_name,captured_by) VALUES(?,?,?)',[$tid,$year,$u['id']]);$id=(int)$GLOBALS['pdo']->lastInsertId();q("INSERT INTO rp_members(tenant_id,cohort_id,student_id,class_id,class_name) SELECT s.tenant_id,?,s.id,s.class_id,COALESCE(c.name,'Unassigned') FROM students s LEFT JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id LEFT JOIN sis_student_details d ON d.student_id=s.id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND COALESCE(d.status,'active')='active'",[$id,$tid]);return 'Immutable active-roster cohort snapshot captured. Label it with the actual school year; missing history is not inferred.';});}
 if($a==='forecast'){$_SESSION['ix_forecast']=rp_forecast($u,sv_qty('days',365),op_bps(op_text('collection_percent',10,true)),op_money(op_text('opening',20,true),true),op_money(op_text('outflow',20,true),true));return 'Scenario estimate calculated from explicit assumptions; this is not a collection guarantee.';}
 throw new RuntimeException('Unsupported reporting action.');
}
function rp_render(array $u):void{
 ix_need($u,'reports_view');$tid=(int)$u['tenant_id'];$tabs=['dashboard'=>'Executive dashboard','reports'=>'Report explorer & comparisons','builder'=>'Custom report builder','exports'=>'Scheduled exports','retention'=>'Retention & year-on-year','forecast'=>'Financial forecasting'];$view=ix_tabs('reports',$tabs,'dashboard');op_card($tabs[$view]);
 if($view==='dashboard'){echo '<div class="ix-kpis">';foreach(rp_report($u,'executive') as $r)echo '<div>'.e($r['metric']).'<strong>'.e($r['value']).'</strong></div>';echo '</div><p>Figures are descriptive. Current roster/class assignments are distinguished from immutable cohort snapshots. Unrecorded attendance is not treated as absence; only published approved academic results enter trends.</p>';}
 elseif($view==='reports'){$allowed=rp_columns();if(!ix_can($u,'finance_reports'))unset($allowed['finance']);if(!ix_can($u,'hr_reports'))unset($allowed['hr']);$key=is_string($_GET['dataset']??null)?$_GET['dataset']:'enrolment';if(!isset($allowed[$key]))$key='enrolment';$f=rp_filters($_GET);echo '<form method="get" class="op-form"><input type="hidden" name="s" value="intelligence"><input type="hidden" name="area" value="reports"><input type="hidden" name="view" value="reports">';op_select('dataset','Dataset',array_combine(array_keys($allowed),array_keys($allowed)));op_field('from','From','date',$f['from']);op_field('to','To','date',$f['to']);op_field('class_id','Class ID (0 for school)','number',(string)$f['class_id']);op_end('Explore');$rows=rp_report($u,$key,$f);op_table($rows,rp_columns()[$key]);$prior=$f;$prior['from']=(new DateTimeImmutable($f['from']))->modify('-1 year')->format('Y-m-d');$prior['to']=(new DateTimeImmutable($f['to']))->modify('-1 year')->format('Y-m-d');echo '<h4>Comparable prior-year range</h4>';op_table(rp_report($u,$key,$prior),rp_columns()[$key]);echo '<p>Attendance class grouping uses current student class; finance debt is current outstanding on the selected invoice cohort, not a reconstructed historical balance. Academic mean is normalized component percentage, not a report-card weighted term total. Workload and transport/hostel values describe current records.</p>';}
 elseif($view==='builder'){foreach(rp_columns() as $key=>$cols){try{rp_require($u,$key);}catch(Throwable $e){continue;}echo '<p><b>'.e($key).'</b>: '.e(implode(', ',$cols)).'</p>';}ix_form('rp_definition',['name'=>['Report name','text'],'dataset'=>['Dataset',array_combine(array_keys(rp_columns()),array_keys(rp_columns()))],'from'=>['From','date',date('Y-01-01')],'to'=>['To','date',date('Y-m-d')],'class_id'=>['Class ID (0 for school)','number','0'],'columns'=>['Comma-separated allowlisted columns in display order','text']],'Save report definition');}
 elseif($view==='exports'){op_table(q('SELECT id,name,dataset FROM rp_definitions WHERE tenant_id=? AND user_id=?',[$tid,$u['id']])->fetchAll(),['ID','Definition','Dataset']);ix_form('rp_export',['definition_id'=>['My definition ID','number']],'Generate private CSV');ix_form('rp_schedule',['definition_id'=>['My definition ID','number'],'frequency'=>['Frequency',['daily'=>'Daily','weekly'=>'Weekly','monthly'=>'Monthly']],'window_days'=>['Rolling report window days','number','30']],'Schedule private export');op_table(q('SELECT id,definition_id,frequency,next_due,active,last_error FROM rp_schedules WHERE tenant_id=? AND user_id=?',[$tid,$u['id']])->fetchAll(),['ID','Definition','Frequency','Next','Active','Review']);ix_form('rp_stop_schedule',['schedule_id'=>['Schedule ID','number']],'Stop schedule');foreach(q('SELECT id,title,expires_at FROM rp_exports WHERE tenant_id=? AND user_id=? ORDER BY id DESC LIMIT 100',[$tid,$u['id']])->fetchAll() as $r)echo '<p><a href="?ix_export='.(int)$r['id'].'">'.e($r['title']).'</a> · expires '.e($r['expires_at']).'</p>';echo '<p>Downloads recheck current permissions, ownership and expiry. CSV cells are protected against spreadsheet formulas. Cron generates private records, not public files.</p>';}
 elseif($view==='retention'){op_table(rp_report($u,'retention'),rp_columns()['retention']);if($u['role']==='school_admin')ix_form('rp_cohort',['year_name'=>['Actual current academic year YYYY/YYYY+1','text']],'Capture immutable current active roster');echo '<p>Retention is intersection of consecutive explicitly captured cohorts. A missing student in a later snapshot is not automatically labelled a dropout; graduation, transfer and data completeness require review. No historical roster is invented.</p>';}
 else{ix_need($u,'finance_reports');ix_form('rp_forecast',['days'=>['Collection horizon days','number','30'],'collection_percent'=>['Assumed collection percentage','number','60'],'opening'=>['Opening available cash (NGN)','text','0'],'outflow'=>['Known expected cash outflows (NGN)','text','0']],'Estimate low/base/high cash scenarios');if(isset($_SESSION['ix_forecast'])){op_table($_SESSION['ix_forecast'],['Scenario','Eligible debt kobo','Collection %','Estimated receipts kobo','Ending cash kobo','Shortfall kobo']);unset($_SESSION['ix_forecast']);}echo '<p>Scenarios use receivables due within the horizon (including undated invoices), your collection assumption ±15 percentage points, opening cash and declared outflows. They exclude unentered future billing/commitments and do not promise collections.</p>';}
 echo '</section>';
}
